import {qrSvg} from '/qr.js';
const $=s=>document.querySelector(s), app=$('#app');
let state=null,session=JSON.parse(sessionStorage.getItem('pt-session')||'null'),wizardStep=0,filter='All',query='',propertyTab='Overview',saving=false,polling=false;
const roles={agency:'Taylor Brooks',tenant:'Alex Morgan',owner:'Jordan Lee',contractor:'Sam Rivera'};
const navs={agency:['Overview','Properties','Onboarding','Maintenance','People','Documents','Tags & access','Notifications','Reports','Settings'],tenant:['Home','Onboarding','Property','Documents','Maintenance','Profile'],owner:['Home','Onboarding','Approvals','Maintenance','Documents','Statements','Profile'],contractor:['Jobs','Profile']};
const paths={Overview:'',Home:'',Jobs:'', 'Tags & access':'tags'};
const icons={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',properties:'M3 21V4h12v17M8 8h2M8 12h2M8 16h2M15 10h6v11M19 14h-1M19 18h-1',onboarding:'M9 4H5v17h14V4h-4M9 3h6v4H9zM8 12l2 2 5-5M8 18h7',maintenance:'M14 6a5 5 0 0 0-6 6L3 17a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-6l-3 3-4-4z',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',documents:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h8',tags:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h3v3h4v4h-7z',notifications:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',reports:'M4 21V11M12 21V3M20 21V7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M4 12h16M14 6l6 6-6 6',plus:'M12 5v14M5 12h14',search:'M20 20l-5-5M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14',chevron:'M9 5l7 7-7 7',check:'M4 12l5 5L20 6',close:'M6 6l12 12M6 18L18 6',clock:'M12 8v5l3 2M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',copy:'M8 8h13v13H8zM16 8V3H3v13h5',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',menu:'M4 6h16M4 12h16M4 18h16',leaf:'M20 3C5 2 1 9 5 16c6 7 15 0 15-13M4 21L16 8'};
const ico=(name='home')=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.home}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const date=v=>new Intl.DateTimeFormat('en-AU',{day:'2-digit',month:'short',year:'numeric',timeZone:'Australia/Sydney'}).format(new Date(v||Date.now()));
const time=v=>new Intl.DateTimeFormat('en-AU',{day:'2-digit',month:'short',hour:'numeric',minute:'2-digit',timeZone:'Australia/Sydney'}).format(new Date(v));
const money=v=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}).format(v||0);
const pill=v=>`<span class="pill ${/new|invited|progress|review|approval|submitted|pending/.test(v)?'amber':/revoked|expired|changes|cancelled|failure/.test(v)?'red':/vacant|draft/.test(v)?'grey':''}">${esc(title(v))}</span>`;
const logo=()=>`<a href="/" data-nav class="logo"><span class="logomark">${ico('tags')}</span>PropertyTag<span style="font-size:10px;margin-left:-7px;align-self:flex-start">®</span></a>`;
const btn=(label,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const art=(i=0)=>`<svg viewBox="0 0 720 380" xmlns="http://www.w3.org/2000/svg" aria-label="Illustrated fictional Sydney terrace" role="img"><defs><linearGradient id="sky${i}" x2="0" y2="1"><stop stop-color="#c6d3c9"/><stop offset="1" stop-color="#e3e7d8"/></linearGradient><linearGradient id="wall${i}"><stop stop-color="${i%2?'#d9c9b0':'#e2dcc9'}"/><stop offset="1" stop-color="#b8b5a0"/></linearGradient></defs><rect width="720" height="380" fill="url(#sky${i})"/><circle cx="570" cy="70" r="48" fill="#f1efd8" opacity=".7"/><path d="M0 290Q80 230 170 275V380H0" fill="#778b6e"/><path d="M535 185Q575 100 650 153Q710 95 750 180V380H535" fill="#637c63"/><path d="M608 150L626 362M560 208l59 60M670 190l-48 85" stroke="#4f6650" stroke-width="10" fill="none"/><path d="M100 155L345 51l235 104z" fill="#505f54"/><rect x="115" y="155" width="450" height="207" fill="url(#wall${i})"/><path d="M108 153h465v15H108zM122 190h436v9H122z" fill="#f0eddf"/><path d="M345 72l178 77H170z" fill="#c9c9b6"/><circle cx="345" cy="123" r="19" fill="#657567" stroke="#e7e6d5" stroke-width="7"/><rect x="310" y="237" width="66" height="125" fill="#365244"/><rect x="320" y="249" width="46" height="58" fill="#647c6a"/><circle cx="363" cy="322" r="3" fill="#cbbb8f"/>${[165,245,410,490].map(x=>`<rect x="${x}" y="216" width="42" height="92" fill="#edf0df"/><rect x="${x+5}" y="221" width="32" height="80" fill="#637b6b"/><path d="M${x+21} 221v80M${x+5} 260h32" stroke="#d8decb" stroke-width="3"/>`).join('')}<path d="M105 325h192v32H105zM388 325h192v32H388z" fill="#adb4a0"/>${Array.from({length:22},(_,j)=>`<path d="M${111+j*9} 326v31" stroke="#4f6556" stroke-width="2"/>`).join('')}${Array.from({length:21},(_,j)=>`<path d="M${391+j*9} 326v31" stroke="#4f6556" stroke-width="2"/>`).join('')}<rect x="95" y="317" width="15" height="47" fill="#d2d3bc"/><rect x="573" y="317" width="15" height="47" fill="#d2d3bc"/><rect y="363" width="720" height="17" fill="#a5ad97"/><path d="M290 380l20-18h66l22 18z" fill="#d8d9c6"/><path d="M59 360v-95M30 310q-22-60 22-67q54 7 32 69" fill="#486c52" stroke="#486c52" stroke-width="9"/><text x="700" y="367" fill="#425344" font-family="Arial" font-size="8" text-anchor="end">FICTIONAL PROPERTY · ILLUSTRATION</text></svg>`;
const property=id=>state.properties.find(p=>p.id===id)||{address:'Assigned property',suburb:''};
const ptext=id=>{const p=property(id);return `${p.address}, ${p.suburb}`;};
const href=(role,n)=>'/'+role+'/'+(paths[n]??n.toLowerCase()).replace(/\/$/,'');
const current=()=>{const p=location.pathname.split('/').filter(Boolean);return {role:p[0]||'',section:p[1]||'',id:p[2]||''};};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(session?{Authorization:'Bearer '+session.token}:{})},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
async function act(action,data={}){while(saving)await new Promise(r=>setTimeout(r,25));saving=true;try{const d=await api('action',{action,...data});state=d.state;return d;}catch(e){toast(e.message);throw e;}finally{saving=false;}}
async function sign(role,path){try{session=await api('persona',{role});sessionStorage.setItem('pt-session',JSON.stringify(session));state=await api('state');wizardStep=state.onboarding.find(o=>o.person===session.person)?.step||0;closeModal();go(path||'/'+role);}catch(e){toast(e.message);}}
function go(path){history.pushState({},'',path);filter='All';query='';propertyTab='Overview';render();window.scrollTo(0,0);}
function openModal(title,html){$('#modal').innerHTML=`<div class="modalhead"><h2>${title}</h2>${btn(ico('close'),'close','','ghost small')}</div><div class="modalbody">${html}</div>`;$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();}
function timeline(events=state.audit,limit=6){return `<ul class="timeline">${events.slice(0,limit).map(e=>`<li><strong>${esc(e.action)}</strong><small>${esc(e.actor)} · ${time(e.time)}</small>${e.after?`<small>${esc(e.after)}</small>`:''}</li>`).join('')||'<li>No activity yet.</li>'}</ul>`;}
function disclosure(){return `<div class="disclosurebar"><span>Demonstration · fictional properties and people</span><a href="/demo-disclosure" data-nav>What’s simulated? ↗</a></div>`;}
function heading(title,sub,actions='',eyebrow='Workspace'){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function shell(content,section){const role=session.role,unread=state.notifications.filter(n=>!n.read).length;if(role==='agency'){return `<div class="app-shell"><aside class="sidebar">${logo()}<div class="agency-name"><strong>${esc(state.agency)}</strong><span class="muted">Property management workspace</span></div><p class="navlabel">Your workspace</p><nav>${navs.agency.map((n,i)=>`<a data-nav href="${href(role,n)}" class="${(paths[n]??n.toLowerCase())===section?'active':''}">${ico(['home','properties','onboarding','maintenance','people','documents','tags','notifications','reports','settings'][i])}${n}${n==='Onboarding'?`<span class="count">${state.onboarding.filter(o=>o.status!=='activated').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><button data-action="controls" class="ghost small">${ico('shield')} Demo workspace</button><p>ONE PROPERTY.<br>ONE CONNECTED RECORD.</p></div></aside><div class="workspace"><header class="topbar"><button class="ghost small mobile-only" data-action="navigation" aria-label="Open navigation">${ico('menu')}</button><form id="search-form" class="searchbox">${ico('search')}<input aria-label="Search portfolio" name="q" placeholder="Search properties, people, anything…"><kbd>⌘ K</kbd></form><div class="row topprofile"><button class="ghost small" data-action="notifications" aria-label="Notifications">${ico('notifications')}${unread?`<small>${unread}</small>`:''}</button><span class="avatar">TB</span><div>Taylor Brooks<small>Property manager</small></div></div></header><main class="main">${content}${disclosure()}</main></div></div>`;}return `<div class="portal-shell"><header class="portal-top">${logo()}<div class="agency">${esc(state.agency)}<small style="display:block;margin-top:5px">${esc(session.person)} · ${title(role)}</small></div></header><div class="portal-content"><nav class="portal-nav">${navs[role].map(n=>`<a href="${href(role,n)}" data-nav class="${(paths[n]??n.toLowerCase())===section?'active':''}">${n}</a>`).join('')}</nav>${content}${disclosure()}</div></div>`;}
function landing(){return `<div class="landing"><header>${logo()}<span class="eyebrow">Connected property operations</span></header><main><div class="landing-grid"><div><span class="pill">The property, connected.</span><h1>One property.<br>One connected<br><em>record.</em></h1><p class="lead">A simpler way to bring owners, tenants, contractors and your agency together. Less paperwork. Fewer follow-ups. A clear next step for everyone.</p><div class="actions">${btn('Launch interactive demo '+ico('arrow'),'launch','','primary')}${btn('Explore the four portals','controls')}</div><p class="note" style="margin-top:18px">A working demonstration. Fictional data. Real connected workflows.</p></div><div class="landing-visual"><span class="visualtag">HCP–1024 · BALMAIN</span><div class="art">${art()}</div><div class="floating-record"><div class="row between"><span class="eyebrow">Your connected property</span>${pill('Active')}</div><h3>12 Darling Street</h3><p class="note">Balmain NSW 2041 · Fictional demonstration</p><hr class="divider"><div class="row between"><div class="row"><span class="avatar">AM</span><div style="font-size:11px">Alex’s onboarding<small style="display:block;margin-top:4px;color:var(--muted)">Ready for the next chapter</small></div></div>${ico('chevron')}</div><div class="progress" style="margin-top:17px"><i style="width:67%"></i></div></div><p style="color:#c4d1bd;text-align:center;font-size:9px;letter-spacing:2px;margin:25px 0">SCAN. CONNECT. KEEP MOVING.</p></div></div><div class="landing-footer">${[['01','Agency workspace','One place for the work that needs you.'],['02','Tenant portal','A clear path from invitation to move-in.'],['03','Owner portal','Approvals and updates without the chasing.'],['04','Contractor portal','The right job. The right information.']].map(([n,t,p])=>`<div><span class="eyebrow">${n}</span><strong style="margin-top:12px">${t}</strong>${p}</div>`).join('')}</div>${disclosure()}</main></div>`;}
function dashboard(){const review=state.onboarding.filter(o=>['submitted','under_review'].includes(o.status)),open=state.jobs.filter(j=>!['closed','completed','cancelled'].includes(j.status)),approve=state.jobs.filter(j=>j.status==='awaiting_owner_approval');return `${heading('Good morning, Taylor.','Here’s what’s happening across your portfolio today.',`<span class="datebadge">${date()}</span>${btn(ico('plus')+' Invite someone','invite','','primary')}`,'Your day, at a glance')}<div class="metrics">${[[state.properties.length,'Properties managed','Illustrative portfolio'],[state.onboarding.filter(o=>o.status!=='activated').length,'Onboarding in progress',review.length+' ready for review'],[open.length,'Open maintenance',open.filter(j=>j.severity==='Urgent').length+' flagged urgent'],[approve.length,'Owner approvals','Waiting for a decision']].map(([v,l,t])=>`<div class="metric"><span class="label">${l}</span><div class="number">${v.toString().padStart(2,'0')}</div><small>${t}</small></div>`).join('')}</div><div class="banner"><div><h2>One small tag. A more connected property.</h2><p>Give every property a secure doorway to its documents, people and next steps.</p></div>${btn('Explore tags '+ico('arrow'),'go-tags','','small')}</div><div class="grid2"><section class="panel flush"><div class="panelhead"><h2>Needs your attention <span class="pill grey">${review.length+approve.length+state.jobs.filter(j=>j.status==='new').length} items</span></h2><a data-nav class="link" href="/agency/onboarding">View all ${ico('chevron')}</a></div><div class="tablewrap"><table><thead><tr><th>Property / task</th><th>Status</th><th>Next step</th></tr></thead><tbody>${review.map(o=>`<tr><td><strong>${esc(ptext(o.property))}</strong><small>${esc(o.person)} · Onboarding</small></td><td>${pill(o.status)}</td><td><a data-nav class="link" href="/agency/onboarding/${o.id}">Review file →</a></td></tr>`).join('')}${[...approve,...state.jobs.filter(j=>j.status==='new')].map(j=>`<tr><td><strong>${esc(ptext(j.property))}</strong><small>${esc(j.title)} · ${j.id}</small></td><td>${pill(j.status)}</td><td><a data-nav class="link" href="/agency/maintenance/${j.id}">${j.status==='new'?'Triage request':'View approval'} →</a></td></tr>`).join('')}${review.length+approve.length+state.jobs.filter(j=>j.status==='new').length===0?'<tr><td colspan="3">You’re all caught up.</td></tr>':''}</tbody></table></div></section><section class="panel"><div class="row between" style="margin-bottom:24px"><h2 style="margin:0">Quick actions</h2><span class="eyebrow">Make a start</span></div><div class="quickactions">${btn(ico('people')+' Invite tenant','invite','data-role="tenant"')}${btn(ico('onboarding')+' Invite owner','invite','data-role="owner"')}${btn(ico('maintenance')+' New work order','create-job')}${btn(ico('tags')+' Generate tag','invite','data-role="hub"')}</div><hr class="divider"><h3>Recently connected</h3><div class="row"><span class="avatar">JL</span><div style="font-size:12px">Jordan Lee<small class="muted" style="display:block;margin-top:5px">Owner · 12 Darling Street</small></div><span style="margin-left:auto">${pill('active')}</span></div></section></div><div class="grid2" style="margin-top:23px"><section class="panel flush"><div class="panelhead"><h2>Your portfolio</h2><a data-nav href="/agency/properties" class="link">All properties →</a></div>${propertyTable(state.properties.slice(0,3))}</section><section class="panel"><div class="row between" style="margin-bottom:23px"><h2 style="margin:0">Latest activity</h2>${btn('Full log','activity','','link')}</div>${timeline(state.audit,4)}</section></div>`;}
function propertyTable(ps){return `<div class="tablewrap"><table><thead><tr><th>Property</th><th>Owner</th><th>Stage</th><th></th></tr></thead><tbody>${ps.map((p,i)=>`<tr class="clickrow" data-action="property" data-id="${p.id}"><td><div class="row"><div class="thumb">${art(i)}</div><div><strong>${esc(p.address)}</strong><small>${esc(p.suburb)} · ${p.ref}</small></div></div></td><td>${esc(p.owner)}</td><td>${pill(p.status.toLowerCase())}</td><td>${ico('chevron')}</td></tr>`).join('')}</tbody></table></div>`;}
function properties(){const ps=state.properties.filter(p=>(filter==='All'||p.status===filter)&&Object.values(p).some(v=>String(v).toLowerCase().includes(query.toLowerCase())));return `${heading('Your property portfolio.','Every property, its people and the work in progress.',btn(ico('plus')+' Add property','add-property','','primary'),'Properties')}<div class="row between wrap" style="margin-bottom:18px"><div class="filters" style="margin:0">${['All','Active','Onboarding','Vacant','Invited'].map(f=>btn(f,'filter',`data-value="${f}"`,filter===f?'active':'')).join('')}</div><input aria-label="Search properties" id="portfolio-search" placeholder="Search address, owner or tenant…" value="${esc(query)}" style="max-width:280px"></div><section class="panel flush">${ps.length?propertyTable(ps):'<div class="empty">No properties match your search.</div>'}</section>`;}
function propertyDetail(id){const p=property(id);if(!p.id)return '<div class="empty">Property not found.</div>';const jobs=state.jobs.filter(j=>j.property===id),obs=state.onboarding.filter(o=>o.property===id);const tab=propertyTab;return `<a class="link" data-nav href="/agency/properties">← Back to portfolio</a><div class="propertyhero" style="margin-top:20px"><div class="art">${art(state.properties.indexOf(p))}</div><div class="property-details"><div class="row between"><span class="eyebrow">${p.ref} · Illustrative property</span>${pill(p.status.toLowerCase())}</div><h1 style="margin-top:18px">${esc(p.address)}</h1><p class="muted" style="font-size:13px">${esc(p.suburb)} NSW ${p.postcode}</p><div class="statrow"><div><span class="muted">Weekly rent</span><strong>${money(p.rent)}</strong></div><div><span class="muted">Bedrooms</span><strong>${p.beds}</strong></div><div><span class="muted">Bathrooms</span><strong>${p.baths}</strong></div></div></div></div><div class="tabs">${['Overview','People','Onboarding','Documents','Maintenance','Tags & access','Activity'].map(t=>btn(t,'property-tab',`data-value="${t}"`,t===tab?'active':'')).join('')}</div>${tab==='Overview'?`<div class="grid2"><div class="panel"><h2>The connected record</h2><p class="note">Fictional demonstration property. Linked people, documents and workflows stay together through every stage.</p>${person(p.owner,'Property owner','JL')}${person(p.tenant,'Incoming tenant','AM')}${person('Taylor Brooks','Property manager','TB')}<hr class="divider"><h3>Tenancy snapshot</h3><div class="summaryrow"><span>Proposed term</span>01 Nov 2026 – 31 Oct 2027</div><div class="summaryrow"><span>Rent</span>${money(p.rent)} / week · demo only</div><div class="summaryrow"><span>Checklist</span>Agreement · condition report · by-laws · RBO</div></div><div class="panel"><h2>Next actions</h2>${obs.map(o=>`<div class="summaryrow"><a href="/agency/onboarding/${o.id}" data-nav>${esc(o.person)} →</a>${pill(o.status)}</div>`).join('')}${jobs.map(j=>`<div class="summaryrow"><a href="/agency/maintenance/${j.id}" data-nav>${j.id} →</a>${pill(j.status)}</div>`).join('')}${btn('Invite to property','invite',`data-property="${id}"`,'primary small')}<hr class="divider"><h3>Property notices</h3><p class="note">No shared access codes are stored in this demonstration. Building guidance is available through the public property hub.</p></div></div>`:tab==='People'?`<div class="panel">${person(p.owner,'Owner','JL')}${person(p.tenant,'Tenant','AM')}${person(p.manager,'Manager','TB')}</div>`:tab==='Onboarding'?onboardingTable(obs):tab==='Documents'?documents(id):tab==='Maintenance'?jobList(jobs):tab==='Tags & access'?tags(id):`<div class="panel">${timeline(state.audit.filter(e=>e.entity===id),40)}</div>`}`;}
function person(name,role,initial){return `<div class="personcard"><span class="avatar">${initial}</span><div>${esc(name)}<small>${role} · Fictional persona</small></div></div>`;}
function onboardingTable(obs=state.onboarding){return `<section class="panel flush"><div class="tablewrap"><table><thead><tr><th>Person & property</th><th>Role</th><th>Progress</th><th>Status</th><th></th></tr></thead><tbody>${obs.map(o=>`<tr><td><strong>${esc(o.person)}</strong><small>${esc(ptext(o.property))}</small></td><td>${title(o.role)}</td><td><div class="progress" style="width:90px"><i style="width:${o.status==='activated'?100:(o.step+1)/6*100}%"></i></div><small>${o.status==='activated'?6:o.step+1} of 6 steps</small></td><td>${pill(o.status)}</td><td><a data-nav class="link" href="/agency/onboarding/${o.id}">Open file →</a></td></tr>`).join('')}</tbody></table></div></section>`;}
function onboardingQueue(){return `${heading('A clear path to move-in.','Track the missing pieces, review submissions and activate the next chapter.',btn(ico('plus')+' Create invitation','invite','','primary'),'Onboarding')}<div class="filters">${['All','invited','submitted','under_review','changes_requested','activated'].map(f=>btn(title(f),'filter',`data-value="${f}"`,filter===f?'active':'')).join('')}</div>${onboardingTable(state.onboarding.filter(o=>filter==='All'||o.status===filter))}`;}
function review(id){const o=state.onboarding.find(o=>o.id===id);if(!o)return '<div class="empty">File not found.</div>';return `<a data-nav class="link" href="/agency/onboarding">← All onboarding files</a>${heading(esc(o.person),esc(ptext(o.property)),pill(o.status),'Onboarding / Staff review')}<div class="grid2"><section class="panel"><h2>Submission checklist</h2><p class="note">Each review is recorded. All three checks must pass before approval and activation.</p>${[['details','Contact & emergency details'],['document','Synthetic document'],['agreement','Agreement acknowledgement']].map(([key,label])=>`<div class="summaryrow" style="align-items:center"><div><strong>${label}</strong><p class="note" style="margin:7px 0 0">${key==='details'?esc(o.data.email||'Not provided'):key==='document'?esc(o.data.document||'No document provided'):'Simulation · non-binding'}</p></div>${o.reviews.includes(key)?pill('reviewed'):btn('Mark reviewed','review',`data-id="${id}" data-review="${key}"`,'small')}</div>`).join('')}<hr class="divider"><h3>Submitted details</h3>${Object.entries(o.data).map(([k,v])=>`<div class="summaryrow"><span>${title(k)}</span><strong>${esc(String(v))}</strong></div>`).join('')}${o.correction?`<p class="notice">Correction note: ${esc(o.correction)}</p>`:''}</section><section class="panel"><h2>Review decision</h2><p class="note">Review the supplied demo information. Activation follows explicit staff approval.</p><div class="stack">${btn('Approve onboarding','review',`data-id="${id}" data-next="approved"`,'primary')}${btn('Activate '+(o.role==='owner'?'management':'tenancy'),'review',`data-id="${id}" data-next="activated"`,'primary')}${btn('Request corrections','correction',`data-id="${id}"`)}</div><hr class="divider"><h3>File activity</h3>${timeline(state.audit.filter(e=>e.entity===id),8)}<div class="notice">Documents and acknowledgements are synthetic. This review does not verify identity or produce a legally binding agreement.</div></section></div>`;}
function jobList(jobs=state.jobs){return `<div class="grid3">${jobs.map(j=>`<a data-nav href="/${session.role}/${session.role==='contractor'?'jobs':'maintenance'}/${j.id}" class="jobcard"><div class="row between"><span class="eyebrow">${j.id}</span>${pill(j.status)}</div><h3>${esc(j.title)}</h3><p>${esc(ptext(j.property))}</p><div class="row between"><small class="muted">${date(j.created)}</small>${j.quote!==undefined&&j.quote>0?`<strong style="font-size:13px">${money(j.quote)}</strong>`:ico('arrow')}</div></a>`).join('')||'<div class="empty">No work orders in this view.</div>'}</div>`;}
function maintenance(){const isAgency=session.role==='agency';return `${heading(isAgency?'Keep every request moving.':session.role==='contractor'?'Your assigned work.':'Maintenance, without the mystery.',isAgency?'Triage, approvals and work orders. One shared status.':'Follow the progress of each request from the first report to completion.',['agency','tenant'].includes(session.role)?btn(ico('plus')+' Report maintenance','create-job','','primary'):'',isAgency?'Maintenance':'Property care')}${session.role==='tenant'?'<div class="notice" style="margin-bottom:20px">Immediate danger? Call 000. Urgent repairs need human escalation through your agency’s emergency contact. Do not wait for this demonstration workflow.</div>':''}${isAgency?`<div class="board">${[['Incoming',['new','triage']],['Approval',['awaiting_owner_approval','approved']],['In motion',['assigned','scheduled','in_progress']],['Completed',['completed','closed']]].map(([label,statuses])=>`<div class="board-col"><h3>${label}<span class="muted">${state.jobs.filter(j=>statuses.includes(j.status)).length}</span></h3>${state.jobs.filter(j=>statuses.includes(j.status)).map(j=>`<a data-nav class="jobcard" href="/agency/maintenance/${j.id}"><div class="row between"><span class="eyebrow">${j.id}</span>${j.severity==='Urgent'?pill('Urgent'):''}</div><h3>${esc(j.title)}</h3><p>${esc(ptext(j.property))}</p>${pill(j.status)}${j.quote?`<small style="float:right">${money(j.quote)}</small>`:''}</a>`).join('')||'<p class="note">Nothing waiting here.</p>'}</div>`).join('')}</div>`:jobList()}`;}
function jobDetail(id){const j=state.jobs.find(j=>j.id===id);if(!j)return '<div class="empty">This work order is unavailable to your role.</div>';const role=session.role;let actions='';if(role==='agency'){if(j.status==='new')actions=btn('Begin triage','job-next',`data-id="${id}" data-next="triage"`,'primary');if(j.status==='triage')actions=btn('Request owner approval','quote',`data-id="${id}"`,'primary')+btn('Assign unquoted work','job-next',`data-id="${id}" data-next="assigned"`);if(j.status==='approved')actions=btn('Assign Sam Rivera','job-next',`data-id="${id}" data-next="assigned"`,'primary');if(j.status==='completed')actions=btn('Verify & close request','job-next',`data-id="${id}" data-next="closed"`,'primary');if(j.variation?.status==='pending')actions+=btn('Approve variation '+money(j.variation.amount),'variation-approve',`data-id="${id}"`,'primary');}if(role==='owner'&&j.status==='awaiting_owner_approval')actions=btn('Approve '+money(j.quote)+' quote','job-next',`data-id="${id}" data-next="approved"`,'primary')+btn('Decline / request details','owner-decline',`data-id="${id}"`);if(role==='contractor'){if(j.status==='assigned')actions=btn('Accept & propose appointment','schedule',`data-id="${id}"`,'primary');if(j.status==='scheduled')actions=btn('Start work','job-next',`data-id="${id}" data-next="in_progress"`,'primary');if(j.status==='in_progress')actions=btn('Complete work order','complete',`data-id="${id}"`,'primary');if(['scheduled','in_progress'].includes(j.status))actions+=btn('Request variation','variation',`data-id="${id}"`);}
return `<a data-nav href="/${role}/${role==='contractor'?'':'maintenance'}" class="link">← All work orders</a>${heading(esc(j.title),esc(ptext(j.property)),pill(j.status),'Work order / '+id)}${j.severity==='Urgent'?'<div class="notice" style="margin-bottom:20px">Urgent issue: contact agency emergency support. Call 000 if there is immediate danger. This demo does not dispatch emergency services.</div>':''}<div class="grid2"><section class="panel"><div class="row between"><h2>Request details</h2><span class="pill grey">${esc(j.category)}</span></div><p class="note">${esc(j.description||'Routine property maintenance request, seeded for this demonstration.')}</p>${j.photo?`<div class="art" style="height:150px;overflow:hidden;border-radius:6px">${art(2)}</div><p class="note">Synthetic image placeholder · not a real issue photo</p>`:''}<div class="summaryrow"><span>Reported by</span>${esc(j.requester)}</div><div class="summaryrow"><span>Created</span>${date(j.created)}</div>${j.contactWindow?`<div class="summaryrow"><span>Preferred contact</span>${esc(j.contactWindow)}</div>`:''}<div class="summaryrow"><span>Contractor</span>${esc(j.contractor||'Awaiting assignment')}</div>${j.quote!==undefined?`<div class="summaryrow"><span>Quote · AUD · demo only</span>${money(j.quote)}</div>`:''}${j.appointment?`<div class="summaryrow"><span>Proposed appointment</span>${esc(j.appointment)}</div>`:''}${j.variation?`<div class="notice" style="margin-top:15px">Variation: ${money(j.variation.amount)} · ${esc(j.variation.reason)} · ${esc(j.variation.status)}</div>`:''}${j.completion?`<hr class="divider"><h3>Completion notes</h3><p class="note">${esc(j.completion)}</p><p class="note">${esc(j.completionPhoto||'Synthetic seeded completion')} · ${esc(j.invoice||'Demo completion record')}</p>`:''}<hr class="divider"><h3>Conversation</h3>${j.comments.map(c=>`<div class="notice" style="margin:10px 0"><strong>${esc(c.actor)}</strong><br>${esc(c.text)}<br><small>${time(c.time)}</small></div>`).join('')||'<p class="note">No replies yet. Add a message to this request.</p>'}<form id="comment-form" data-id="${id}"><label class="field">Your reply<textarea name="comment" required maxlength="500" placeholder="Add an update…"></textarea></label><button class="small">Add reply</button></form></section><section class="panel"><h2>Next step</h2><div class="stack">${actions||`<p class="note">${role==='tenant'?'Your agency is coordinating this request. Updates will appear here.':j.status==='awaiting_owner_approval'?'Waiting for the owner’s decision.':j.status==='closed'?'Verified and closed by the agency.':'The next step belongs to another role.'}</p>`}</div><hr class="divider"><h3>Shared progress</h3>${['new','triage','awaiting_owner_approval','approved','assigned','scheduled','in_progress','completed','closed'].map(s=>`<div class="summaryrow"><span>${title(s)}</span>${s===j.status?pill(s):'·'}</div>`).join('')}<hr class="divider"><h3>Activity</h3>${timeline(state.audit.filter(e=>e.entity===j.property&&e.action.includes('Maintenance')),8)}</section></div>`;}
function documents(propertyId,statements=false){const docs=state.documents.filter(d=>(!propertyId||d.property===propertyId)&&(!statements||d.folder==='Statements')&&(filter==='All'||d.folder===filter));return `<div class="panel flush"><div class="tablewrap"><table><thead><tr><th>Document</th><th>Folder</th><th>Version</th><th>Status</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><div class="row">${ico('documents')}<div><strong>${esc(d.name)}</strong><small>${esc(ptext(d.property))}</small></div></div></td><td>${d.folder}</td><td>v${d.version}</td><td>${pill('demo preview')}</td><td>${btn('View ↗','document',`data-id="${d.id}"`,'link')}</td></tr>`).join('')||'<tr><td colspan="5">No documents in this folder.</td></tr>'}</tbody></table></div></div>`;}
function documentsPage(statements=false){return `${heading(statements?'Your owner statements.':'The right document. Right here.',statements?'Illustrative statements only. No real trust accounting or financial transactions.':'Role-scoped synthetic records, with a clear version and review status.','',statements?'Statements':'Documents')}${!statements?`<div class="filters">${['All',...new Set(state.documents.map(d=>d.folder))].map(f=>btn(f,'filter',`data-value="${f}"`,filter===f?'active':'')).join('')}</div>`:''}${documents(null,statements)}`;}
function tags(propertyId){const tags=state.tags.filter(t=>!propertyId||t.property===propertyId);return `${!propertyId?heading('One secure doorway.','Give every property a useful physical entry point. Private records always require sign-in.',btn(ico('plus')+' Generate tag','invite','data-role="hub"','primary'),'Tags & access'):''}<div class="grid2"><section class="panel"><div class="tagcard"><div><span class="eyebrow">Harbour & Co · Property hub</span><h2>Good to be<br>connected.</h2><p class="note">Scan for your property guide.<br>Sign in for everything private.</p><span class="pill">NFC + QR ready</span></div><div>${qrSvg(location.origin+'/tag/'+state.properties[0].code)}<p class="qrlabel">Tap or scan</p></div></div><p class="note" style="margin:17px 0">Example property hub · links reveal public guidance only. Create a tag to download a print card.</p><div class="actions">${btn('Print property hub','public-qr',`data-id="${propertyId||'p1'}"`,'small')}${btn('How NFC works','nfc','','small')}</div></section><section class="panel"><h2>Four entry points. One record.</h2>${[['Property hub','Public guidance and secure sign-in.'],['Tenant access','Expiring invitation to guided onboarding.'],['Owner access','Management record and property approvals.'],['Contractor work order','Only the jobs assigned to that contractor.']].map(([h,p])=>`<div class="summaryrow" style="display:block"><strong>${h}</strong><p class="note" style="margin:5px 0 0">${p}</p></div>`).join('')}<p class="notice" style="margin-top:17px">A QR code or NFC tag opens a link. It never grants private access by itself.</p></section></div><section class="panel flush" style="margin-top:22px"><div class="panelhead"><h2>Issued tags & invitations</h2><span class="eyebrow">Server validated</span></div><div class="tablewrap"><table><thead><tr><th>Property / purpose</th><th>Issued to</th><th>Status</th><th>Expires</th><th>Manage</th></tr></thead><tbody>${tags.map(t=>`<tr><td><strong>${esc(ptext(t.property))}</strong><small>${title(t.type)} · ${t.code}</small></td><td>${esc(t.person)}</td><td>${pill(t.revoked?'revoked':t.claimed?'claimed':t.expires<Date.now()?'expired':'issued')}</td><td>${date(t.expires)}</td><td><div class="actions">${t.type==='hub'?btn('Print','public-qr',`data-id="${t.property}"`,'small'):''}${!t.revoked?btn('Revoke','revoke',`data-id="${t.id}"`,'small danger'):''}${btn('Reissue','invite',`data-role="${t.type}" data-property="${t.property}"`,'small')}</div></td></tr>`).join('')||'<tr><td colspan="5">No tags issued yet. Generate your first tag above.</td></tr>'}</tbody></table></div></section>`;}
function notifications(){return `${heading('Your updates.','The things that changed, and what needs you next.',btn('Mark all read','read-notifications','','small'),'Notifications')}<div class="panel">${state.notifications.map(n=>`<div class="personcard"><span class="avatar">${ico(n.read?'check':'notifications')}</span><div>${esc(n.title)}<small>${time(n.time)} · ${n.read?'Read':'Unread'}</small></div></div>`).join('')||'<div class="empty">All quiet for now.</div>'}</div>`;}
function reports(){const submitted=state.onboarding.filter(o=>['submitted','under_review','approved','activated'].includes(o.status)).length,active=state.onboarding.filter(o=>o.status==='activated').length;return `${heading('Make the admin visible.','An illustrative model for a pilot conversation. These are estimates, not observed savings.','','Reports')}<div class="grid2"><section class="panel"><span class="eyebrow">Time saved · adjustable assumptions</span><div class="report-result" id="savings">0 hours</div><p class="note">Illustrative estimate per month</p><form id="report-form" class="fieldgrid"><label class="field">Monthly onboardings<input type="number" name="volume" value="20" min="1" max="500"></label><label class="field">Minutes per manual touch<input type="number" name="minutes" value="6" min="1" max="60"></label><label class="field">Baseline manual touches<input type="number" name="baseline" value="12" min="1" max="100"></label><label class="field">Remaining staff reviews<input type="number" name="remaining" value="4" min="0" max="100"></label></form><p class="notice">Estimated reduction = onboardings × minutes × max(0, baseline − remaining). Staff judgement, compliance checks and review remain.</p></section><section class="panel"><h2>Seeded onboarding funnel</h2><p class="note">Counts derive from this demo’s records.</p><div class="bars" style="margin-bottom:45px">${[['Files',state.onboarding.length],['Submitted',submitted],['Activated',active]].map(([l,v])=>`<div style="height:${Math.max(12,v/state.onboarding.length*120)}px"><span style="position:absolute;top:-20px;left:0;right:0;text-align:center;font-size:12px">${v}</span><small>${l}</small></div>`).join('')}</div><div class="summaryrow"><span>Completion time</span>${medianCompletion()}</div><p class="note">Median uses seeded / submitted timestamps where available. No measured agency savings are claimed.</p><hr class="divider"><h3>Work avoided or moved?</h3><p class="note">Repeated data entry and routine status chasing can be reduced. Document review, exception handling, owner decisions and activation remain with people.</p></section></div>`;}
function medianCompletion(){const hours=state.onboarding.filter(o=>o.submitted).map(o=>(new Date(o.submitted)-new Date(o.created))/3600000).sort((a,b)=>a-b);return hours.length?hours[Math.floor(hours.length/2)].toFixed(1)+' hours · demo':'Not enough submissions';}
function settings(){return `${heading('A familiar agency experience.','Configure the demonstration identity and inspect the simulated integration.','','Agency settings')}<div class="grid2"><section class="panel"><h2>Agency theme</h2><form id="settings-form"><label class="field">Agency display name<input name="agency" maxlength="80" value="${esc(state.agency)}" required></label><label class="field">Accent<select name="theme"><option value="green">Eucalyptus green</option><option value="blue">Harbour blue</option><option value="wine">Deep wine</option></select></label><p class="note">For a customer demo, use “A demonstration prepared for CobdenHayson”. No logo or endorsement is implied.</p><button class="primary">Save theme</button></form><hr class="divider"><h3>Notifications</h3><p class="note">External SMS and email are disabled. All messages remain in the local demo inbox.</p>${state.outbox.map(o=>`<div class="summaryrow"><span>${esc(o.recipient)}</span>${esc(o.status)}</div>`).join('')||'<p class="note">No invitations prepared yet.</p>'}</section><section class="panel"><h2>Property software adapter</h2><p class="note">Vendor-neutral mock adapter. Not a live PropertyMe, PropertyTree or other software connection.</p><div class="actions">${btn('Simulate sync','sync','','small primary')}${btn('Simulate failure','sync','data-failure="true"','small')}</div><hr class="divider">${state.sync.map(s=>`<div class="summaryrow" style="display:block"><div class="row between"><strong>${s.operation}</strong>${pill(s.status.toLowerCase())}</div><p class="note" style="margin:7px 0">${s.entity} · attempt ${s.attempts} · ${time(s.time)}</p><code style="font-size:10px">{ mode: "simulation", status: "${s.status.includes('failure')?'error':'ok'}" }</code>${s.status.includes('failure')?btn('Retry','sync',`data-id="${s.id}"`,'small'):''}</div>`).join('')}</section></div>`;}
function portalHome(){const role=session.role,p=state.properties[0],o=state.onboarding.find(o=>o.person===session.person),jobs=state.jobs.filter(j=>j.property===p?.id),pending=jobs.filter(j=>j.status==='awaiting_owner_approval');return `<div class="greeting-line">Your ${role==='tenant'?'home':'property'}, connected.</div><div class="portalhero">${art()}<div class="overlay"><span class="eyebrow" style="color:#d2dccb;margin-bottom:12px">${esc(state.agency)} · Fictional property</span><h1>${esc(p?.address||'Your property')}</h1><p>${esc(p?.suburb||'')} NSW ${p?.postcode||''} · Welcome, ${esc(session.person.split(' ')[0])}.</p></div></div><div class="grid2"><section class="panel nextaction"><span class="eyebrow">Your next step</span>${o&&o.status!=='activated'?`<h2>${['submitted','under_review','approved'].includes(o.status)?'You’re in good hands.':'Let’s make this feel like home.'}</h2><p class="note">${o.status==='changes_requested'?esc(o.correction):['submitted','under_review','approved'].includes(o.status)?'Your agency is reviewing the details. We’ll keep you updated here.':'A few details now. A smoother move-in ahead. Your progress saves as you go.'}</p><div class="progress" style="margin:20px 0 12px"><i style="width:${(o.step+1)/6*100}%"></i></div><div class="row between"><small class="muted">${o.step+1} of 6 steps</small><a data-nav href="/${role}/onboarding"><button class="primary small">${['submitted','under_review','approved'].includes(o.status)?'View submission':'Continue onboarding'} ${ico('arrow')}</button></a></div>`:role==='owner'&&pending.length?`<h2>A small decision. A job moving.</h2><p class="note">${pending.length} maintenance approval waiting for you. Review the issue and quote before authorising work.</p><a data-nav href="/owner/approvals"><button class="primary">Review approval ${ico('arrow')}</button></a>`:`<h2>Everything in one place.</h2><p class="note">Your ${role==='tenant'?'tenancy':'management'} is active. Find documents, track repairs and see what happens next.</p><a data-nav href="/${role}/documents"><button class="primary">View your documents ${ico('arrow')}</button></a>`}</section><section class="panel"><h2>${role==='tenant'?'Your home at a glance':'Property at a glance'}</h2><div class="summaryrow"><span>${role==='tenant'?'Weekly rent':'Rental snapshot'}</span>${money(p?.rent)} / week</div><div class="summaryrow"><span>Proposed tenancy</span>01 Nov 2026</div><div class="summaryrow"><span>Property manager</span>Taylor Brooks</div><div class="summaryrow"><span>Open maintenance</span>${jobs.filter(j=>!['closed','completed'].includes(j.status)).length} requests</div><p class="note" style="margin-top:15px">Demonstration figures. No rent or bond payments are processed.</p></section></div><div style="margin-top:25px"><div class="row between" style="margin-bottom:17px"><h2 style="margin:0">Property care</h2><a data-nav class="link" href="/${role}/maintenance">View all →</a></div>${jobList(jobs.slice(0,3))}</div>`;}
const stepNames=['Your details','Emergency contact','Documents','Agreement & information','Bond information','Review & submit'];
function wizard(){const o=state.onboarding.find(o=>o.person===session.person);if(!o)return '<div class="empty">No onboarding invitation for this persona. Ask the agency to create one.</div>';const v=o.data,s=wizardStep;if(['submitted','under_review','approved','activated'].includes(o.status))return `<div class="wizard">${heading(o.status==='activated'?'You’re all connected.':'Your details are with the agency.',ptext(o.property),pill(o.status),'Onboarding')}<div class="panel"><h2>${o.status==='activated'?'Your property record is active.':'Thanks, '+esc(session.person.split(' ')[0])+'.'}</h2><p class="note">Your ${session.role==='owner'?'management':'tenancy'} follows the staff review process. Documents, contact details and acknowledgements remain attached to the property.</p>${Object.entries(v).map(([k,v])=>`<div class="summaryrow"><span>${title(k)}</span>${esc(String(v))}</div>`).join('')}<hr class="divider"><a data-nav href="/${session.role}"><button class="primary">Back to your property</button></a></div></div>`;
return `<div class="wizard"><div class="wizardhead"><span class="eyebrow">${session.role==='owner'?'Owner onboarding':'Your next chapter'} · ${esc(ptext(o.property))}</span><h1 style="margin-top:15px">${stepNames[s]}</h1><div class="row between"><span class="note">Step ${s+1} of 6</span><span class="note" id="save-state">Draft saved · resumes here</span></div><div class="stepdots">${stepNames.map((_,i)=>`<span class="${i<=s?'done':''}"></span>`).join('')}</div></div>${o.correction?`<p class="notice">Your agency requested: ${esc(o.correction)}</p>`:''}<section class="panel"><form id="wizard-form" data-id="${o.id}">${s===0?`<h2>A little about you.</h2><p class="note">Use the fictional test persona. Please don’t enter real personal information.</p><div class="fieldgrid"><label class="field">Legal name<input name="name" required value="${esc(v.name)}"></label><label class="field">Preferred name (optional)<input name="preferred" value="${esc(v.preferred)}"></label><label class="field">Email<input name="email" type="email" required value="${esc(v.email)}"></label><label class="field">Phone<input name="phone" required pattern="[+0-9 ()-]{8,20}" placeholder="0400 000 000 · synthetic" value="${esc(v.phone)}"></label><label class="field">Additional occupant (optional)<input name="occupant" value="${esc(v.occupant)}"></label>${session.role==='owner'?`<label class="field">Approval preference<input name="threshold" value="${esc(v.threshold||'Ask before all quoted work')}"></label>`:''}</div>`:s===1?`<h2>Someone to contact, if needed.</h2><p class="note">Basic contact details only. Use fictional information in this demo.</p><label class="field">Emergency contact name<input name="emergency" required value="${esc(v.emergency)}"></label><label class="field">Contact phone<input name="emergencyPhone" required pattern="[+0-9 ()-]{8,20}" value="${esc(v.emergencyPhone)}" placeholder="0400 000 001 · synthetic"></label>`:s===2?`<h2>Your documents, safely demonstrated.</h2><div class="upload">${ico('documents')}<strong id="document-name">${esc(v.document||'Add a synthetic placeholder')}</strong><p>This demo records a filename only. File contents never leave your device. Do not select real ID or sensitive documents.</p><input type="file" id="synthetic-upload" accept=".pdf,.jpg,.jpeg,.png" aria-label="Choose a synthetic placeholder file"><input type="hidden" name="document" value="${esc(v.document)}">${btn('Use demo document','demo-document','','small')}</div><p class="notice" style="margin-top:18px">Demo document — not identity verified. PDF / JPG / PNG · maximum 5 MB.</p>`:s===3?`<h2>Know what you’re agreeing to.</h2><p class="note">Preview only. Your agency must review and supply appropriate production documents.</p><div class="stack">${btn('View proposed demo agreement','preview-agreement','','small')}<a class="link" target="_blank" rel="noopener" href="https://www.nsw.gov.au/housing-and-construction/rules/information-a-tenant-should-get-at-start-of-a-tenancy">NSW tenancy information statement ↗</a><p class="note">Entry condition report and strata by-laws (where applicable) are included in the property document checklist.</p></div><label class="check"><input name="agreement" type="checkbox" ${v.agreement?'checked':''} required><span>I have reviewed the demonstration ${session.role==='owner'?'management':'tenancy'} agreement, information and condition-report checklist. This acknowledgement has no legal effect.</span></label>`:s===4?`<h2>${session.role==='owner'?'Your approval preferences.':'Bond information, clearly explained.'}</h2><p class="note">Rental Bonds Online is a NSW government service. The agency invitation happens separately. This demonstration does not collect, pay or lodge bond money.</p><a target="_blank" rel="noopener" class="link" href="https://www.nsw.gov.au/housing-and-construction/renting-a-place-to-live/residential-rental-bonds/rental-bonds-online-for-tenants">Visit official Rental Bonds Online information ↗</a><label class="check"><input type="checkbox" name="bond" required ${v.bond?'checked':''}><span>I understand the separate government flow. Mark a simulated invitation acknowledgement only.</span></label>`:`<h2>One last look.</h2>${[['Name',v.name],['Email',v.email],['Phone',v.phone],['Emergency contact',v.emergency],['Document',v.document]].map(([k,v])=>`<div class="summaryrow"><span>${k}</span>${esc(v)}</div>`).join('')}<div class="actions" style="margin:16px 0">${stepNames.slice(0,5).map((t,i)=>btn('Edit '+t,'wizard-edit',`data-step="${i}"`,'small')).join('')}</div><label class="field">Demo signature · type the fictional persona name<input name="signature" value="${esc(v.signature)}" required placeholder="${esc(session.person)}"></label><label class="check"><input type="checkbox" name="consent" required ${v.consent?'checked':''}><span>I confirm this is fictional demonstration information. This simulated acknowledgement is non-binding and is not a verified electronic signature.</span></label><div class="notice">Submitting creates a staff review task. Activation follows review and approval.</div>`}<div class="stepnav">${s>0?btn('← Back','wizard-back','','ghost'):btn('Save & exit','wizard-exit','','ghost')}<button class="primary" type="submit">${s===5?'Submit for review':'Save & continue'} ${ico('arrow')}</button></div></form></section></div>`;}
function profile(){return `${heading('Your demo profile.','Fictional details used across this demonstration.','','Preferences')}<div class="panel" style="max-width:600px">${person(session.person,title(session.role)+' persona',session.person.split(' ').map(x=>x[0]).join(''))}<form id="profile-form" style="margin-top:25px"><label class="field">Preferred contact method<select name="contact"><option ${state.preferences?.[session.person]?.contact==='In-app updates'?'selected':''}>In-app updates</option><option ${state.preferences?.[session.person]?.contact==='Demo email inbox'?'selected':''}>Demo email inbox</option></select></label><label class="check"><input type="checkbox" name="updates" checked>Keep me updated about my property requests.</label><button class="primary">Save preferences</button></form><hr class="divider"><p class="note">Production authentication and identity verification are outside this fictional demonstration. Contact details are collected in onboarding.</p></div>`;}
function approvals(){const jobs=state.jobs.filter(j=>j.status==='awaiting_owner_approval');return `${heading('A clear decision. A job moving.','Review the issue, proposed work and quote before approving.','','Owner approvals')}${jobList(jobs)}`;}
function render(){const c=current();if(c.role==='privacy'||c.role==='demo-disclosure'){app.innerHTML=`<div class="portal-content">${logo()}<div style="margin-top:40px">${heading('A real workflow. Fictional data.','PropertyTag / Opryn demonstration disclosure')}<section class="panel"><h2>What this demonstration does</h2><p class="note">It saves fictional onboarding, maintenance, approval and tag data in a shared database. Demo personas show four separately scoped role experiences.</p><h2>What is simulated</h2><p class="note">Identity confirmation, signatures, document contents, notifications, invoices, statements and property software sync. No real email, SMS, payments, bond lodgements or vendor connection occurs.</p><h2>Privacy</h2><p class="note">Use fictional details only. Uploaded files are not transferred; only filenames and synthetic metadata are saved. Demo records can be reset. This owner-private app is not designed for real tenant, owner or banking information.</p><h2>Public tags and access</h2><p class="note">Public tags open non-sensitive guidance. Invitation links expire, can be revoked, and require an explicit demo persona claim. A property tag is not a private account credential.</p><h2>Before real-world use</h2><p class="note">Production authentication, data retention, privacy and security assessment, legal template review and vendor integration discovery are required. Savings are illustrative, not measured.</p><a href="/" data-nav><button class="primary">Back to the demo</button></a></section></div></div>`;return;}
if(c.role==='tag'){publicHub(c.section);return;}if(c.role==='invite'){invitation(c.section);return;}if(!c.role){app.innerHTML=landing();return;}if(c.role==='demo'){app.innerHTML=landing();controls();return;}if(!session||!state||!roles[c.role]){app.innerHTML=landing();if(roles[c.role])sign(c.role,location.pathname);return;}if(c.role!==session.role){sign(c.role,location.pathname);return;}
document.documentElement.style.setProperty('--green',state.theme==='blue'?'#244b5c':state.theme==='wine'?'#653a40':'#214e40');let content='';if(c.role==='agency'){content=c.section===''?dashboard():c.section==='properties'?(c.id?propertyDetail(c.id):properties()):c.section==='onboarding'?(c.id?review(c.id):onboardingQueue()):c.section==='maintenance'?(c.id?jobDetail(c.id):maintenance()):c.section==='documents'?documentsPage():c.section==='tags'?tags():c.section==='notifications'?notifications():c.section==='reports'?reports():c.section==='settings'?settings():c.section==='people'?`${heading('People make a property.','Every person linked to the right property, with the right access.',btn('Invite someone','invite','','primary'),'People')}<div class="grid3">${Object.entries(roles).map(([r,n])=>`<section class="panel">${person(n,title(r),n.split(' ').map(x=>x[0]).join(''))}<p class="note" style="margin-top:17px">${r==='agency'?'Assigned portfolio manager':r==='contractor'?'Assigned work orders only':'12 Darling Street · property relationship'}</p>${btn('Open '+r+' view','role',`data-role="${r}"`,'small')}</section>`).join('')}</div>`:'<div class="empty">Page not found.</div>';}else if(c.role==='contractor')content=c.section==='profile'?profile():c.id?jobDetail(c.id):maintenance();else content=c.section===''?portalHome():c.section==='onboarding'?wizard():c.section==='maintenance'||c.section==='requests'?(c.id?jobDetail(c.id):maintenance()):c.section==='documents'?documentsPage():c.section==='statements'?documentsPage(true):c.section==='approvals'?approvals():c.section==='profile'?profile():c.section==='property'||c.section==='properties'?portalProperty():c.section==='notifications'?notifications():'<div class="empty">Page not found.</div>';
app.innerHTML=shell(content,c.section)+`<button class="demo-launcher" data-action="controls"><span class="demo-dot"></span> Demo controls ${ico('chevron')}</button>`;if(c.section==='reports')calcReport();if(c.section==='settings')$('#settings-form [name=theme]').value=state.theme;}
function portalProperty(){return `${heading('Your property guide.','The practical details, together in one place.','','Property')}<div class="portalhero">${art()}<div class="overlay"><h1>${esc(state.properties[0]?.address)}</h1><p>${esc(state.properties[0]?.suburb)} · Fictional demonstration</p></div></div><div class="grid2"><div class="panel"><h2>Living here</h2><p class="note">Keep shared spaces clear. Check local council guidance for bin collection. Contact your agency for maintenance and property-specific questions.</p><div class="notice">For immediate danger, call 000. This demo does not provide live emergency support.</div></div><div class="panel"><h2>Your agency contact</h2>${person('Taylor Brooks','Property manager','TB')}<p class="note" style="margin-top:20px">Use the maintenance conversation to leave a demo message. No real communication is sent.</p><a data-nav href="/${session.role}/maintenance"><button class="primary small">Open maintenance</button></a></div></div>`;}
function controls(){openModal('Your presenter controls',`<div class="notice">Fictional demo only. Every role sees the same saved workflows, with separate access. Each browser tab keeps its own persona.</div><p class="eyebrow">Step into a different perspective</p><div class="persona-grid">${Object.entries(roles).map(([r,n])=>btn(`<span class="avatar">${n.split(' ').map(x=>x[0]).join('')}</span><span><strong>${title(r)}</strong><small>${n}</small></span>`,'role',`data-role="${r}"`)).join('')}</div><div class="rolebox"><h3>Jump to a scenario</h3><div class="actions">${[['Onboarding','/tenant/onboarding','tenant'],['Owner approval','/owner/approvals','owner'],['Contractor work','/contractor','contractor'],['Tags & QR','/agency/tags','agency'],['Staff review','/agency/onboarding','agency']].map(([l,path,r])=>btn(l,'scenario',`data-path="${path}" data-role="${r}"`,'small')).join('')}</div></div><div class="rolebox"><div class="actions">${btn('Guided demo tour','tour','','small')}${btn('Mobile view','mobile','','small')}${btn('Activity log','activity','','small')}${btn('Integration explained','integration','','small')}${btn('Reset to opening state','reset','','small danger')}</div><p class="note" style="margin:17px 0 0">Estimated 8–10 minutes. Start with the agency dashboard, then create an invitation for Alex.</p></div>`);}
function inviteModal(role='tenant',propertyId='p1'){openModal(role==='hub'?'Generate property tag':'Create a demo invitation',`<form id="invite-form"><div class="notice">Links are generated locally in the demo inbox. No email or SMS is sent.</div><label class="field">Property<select name="property">${state.properties.map(p=>`<option value="${p.id}" ${p.id===propertyId?'selected':''}>${esc(ptext(p.id))}</option>`).join('')}</select></label><label class="field">Access purpose<select name="role">${['tenant','owner','contractor','hub'].map(r=>`<option value="${r}" ${r===role?'selected':''}>${r==='hub'?'Public property hub':title(r)+' · '+roles[r]}</option>`).join('')}</select></label><p class="note">Invitations expire after 7 days and may be claimed once. Reissuing revokes earlier links of the same purpose. Tags never bypass sign-in.</p><label class="check"><input type="checkbox" name="expired">Create an expired example (for presenter testing)</label><button class="primary">Generate secure link ${ico('arrow')}</button></form>`);}
function showQR(url,caption,role='hub'){openModal('Your tag is ready',`<div class="tagpreview"><span class="eyebrow">PropertyTag · ${esc(title(role))}</span><h1 style="margin:20px 0">Good to be connected.</h1><p class="note">${esc(caption)}</p><div class="qr">${qrSvg(url)}</div><p class="qrlabel">Tap or scan · NFC ready</p><p class="note">${esc(url)}</p><div class="actions" style="justify-content:center">${btn(ico('copy')+' Copy link','copy',`data-url="${esc(url)}"`,'small')}${btn(ico('download')+' SVG','download-qr',`data-url="${esc(url)}"`,'small')}${btn('PNG','download-png',`data-url="${esc(url)}"`,'small')}${btn('Print card','print','','small')}${btn('Open link','open-url',`data-url="${esc(url)}"`,'small primary')}</div><p class="notice" style="margin-top:22px">${role==='hub'?'Public guidance only. Sign-in is required for private records.':'Demo invitation · one claim · expires in 7 days. Sign-in confirmation required.'}</p><p class="printonly note">DEMONSTRATION — FICTIONAL · Write this same HTTPS URL to an NFC chip using an NFC writer app.</p></div>`);}
async function publicHub(code){app.innerHTML='<div class="loading">PropertyTag<span>Checking this property doorway…</span></div>';try{const d=await api('public?code='+encodeURIComponent(code));app.innerHTML=`<div class="portal-content" style="max-width:650px">${logo()}<div style="margin-top:45px">${heading('A useful doorway.','Your public property guide. No private information appears here.','',''+esc(d.agency))}<div class="panel"><h2>Good to know</h2>${d.guide.map(g=>`<div class="summaryrow">${esc(g)}</div>`).join('')}<div class="notice" style="margin:22px 0">Immediate danger? Call 000. Contact the agency directly for urgent repairs.</div><p class="note">${esc(d.message)}</p>${btn('Sign in to a demo persona','controls','','primary')}</div>${disclosure()}</div></div>`;}catch(e){app.innerHTML=`<div class="portal-content">${logo()}<div class="panel" style="margin-top:40px"><h1>Let’s reconnect you.</h1><p class="error">${esc(e.message)}</p><p class="note">Ask your agency to check or reissue the tag.</p><a data-nav href="/"><button>Back to demo</button></a></div></div>`;}}
async function invitation(token){app.innerHTML='<div class="loading">PropertyTag<span>Validating your invitation…</span></div>';try{const d=await api('invite?token='+encodeURIComponent(token));app.innerHTML=`<div class="portal-content" style="max-width:620px">${logo()}<div style="margin-top:40px">${heading('Welcome, '+esc(d.person.split(' ')[0])+'.','One connected record for the next chapter.','',''+esc(d.agency))}<section class="panel"><span class="pill">Invitation validated</span><h2 style="margin-top:23px">${esc(d.property)}</h2><p class="note">Continue as the fictional ${d.role} ${esc(d.person)}. This simulates a one-time-code sign-in. No real identity check or SMS occurs.</p><form id="claim-form" data-token="${esc(token)}"><label class="check"><input type="checkbox" name="confirm" required>I confirm this fictional demo persona and agree to use synthetic information only.</label><button class="primary">Confirm demo sign-in ${ico('arrow')}</button></form></section>${disclosure()}</div></div>`;}catch(e){app.innerHTML=`<div class="portal-content">${logo()}<section class="panel" style="margin-top:40px"><span class="pill red">Link unavailable</span><h1 style="margin-top:22px">This doorway needs a new key.</h1><p class="note">${esc(e.message)}</p>${btn('Return to agency to reissue','role','data-role="agency"','primary')}</section></div>`;}}
function calcReport(){const f=$('#report-form');if(!f)return;const v=Object.fromEntries(new FormData(f));$('#savings').textContent=(Number(v.volume)*Number(v.minutes)*Math.max(0,Number(v.baseline)-Number(v.remaining))/60).toFixed(1)+' hours';}
function saveDraftData(){const f=$('#wizard-form');if(!f)return {};const d=Object.fromEntries(new FormData(f));for(const k of ['agreement','bond','consent'])if(f.querySelector(`[name=${k}]`))d[k]=!!f.querySelector(`[name=${k}]`).checked;return d;}
async function saveWizard(step=wizardStep){const f=$('#wizard-form');if(!f)return;return act('save_onboarding',{id:f.dataset.id,data:saveDraftData(),step});}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
document.addEventListener('click',async e=>{const link=e.target.closest('a[data-nav]');if(link){e.preventDefault();go(link.getAttribute('href'));return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{
if(a==='close')closeModal();else if(a==='launch')await sign('agency');else if(a==='role')await sign(b.dataset.role);else if(a==='scenario')await sign(b.dataset.role,b.dataset.path);else if(a==='controls')controls();else if(a==='navigation')openModal('Your workspace',`<div class="stack">${navs.agency.map(n=>`<a data-nav href="${href('agency',n)}">${n} →</a>`).join('')}</div>`);else if(a==='filter'){filter=b.dataset.value;render();}else if(a==='go-tags')go('/agency/tags');else if(a==='property')go('/agency/properties/'+id);else if(a==='property-tab'){propertyTab=b.dataset.value;render();}else if(a==='invite')inviteModal(b.dataset.role||'tenant',b.dataset.property||'p1');else if(a==='revoke'){await act('revoke',{id});toast('Link revoked. Old invitations will no longer validate.');render();}else if(a==='public-qr'){const p=property(id);showQR(location.origin+'/tag/'+p.code,p.address+' · Fictional property hub');}else if(a==='copy'){await navigator.clipboard.writeText(b.dataset.url);toast('Link copied.');}else if(a==='download-qr')download(new Blob([qrSvg(b.dataset.url)],{type:'image/svg+xml'}),'propertytag-demo.svg');else if(a==='download-png'){const image=new Image();image.onload=()=>{const c=document.createElement('canvas');c.width=c.height=980;const ctx=c.getContext('2d');ctx.drawImage(image,0,0,980,980);c.toBlob(blob=>download(blob,'propertytag-demo.png'));};image.src='data:image/svg+xml;base64,'+btoa(qrSvg(b.dataset.url));}else if(a==='print')window.print();else if(a==='open-url'){closeModal();go(new URL(b.dataset.url).pathname);}else if(a==='nfc')openModal('The same doorway, on NFC',`<p class="note">Generate a tag and copy its HTTPS link. A common NFC writer app can write that same URL to a compatible NFC chip. Test the scan, label the tag, and issue it to the right property.</p><p class="notice">Physical writing and NFC hardware are outside this demo. Private records still require sign-in. Reissue an invitation if a chip or printed code is lost.</p>`);
else if(a==='review'){await act('review_onboarding',{id,review:b.dataset.review,next:b.dataset.next});toast('Review saved.');render();}else if(a==='correction')openModal('Request a correction',`<form id="correction-form" data-id="${id}"><label class="field">What needs updating?<textarea name="reason" required placeholder="Please confirm your contact phone number."></textarea></label><button class="primary">Return to ${esc(state.onboarding.find(o=>o.id===id).person)}</button></form>`);
else if(a==='create-job')openModal('Report maintenance',`<form id="job-form">${session.role==='agency'?`<label class="field">Property<select name="property">${state.properties.map(p=>`<option value="${p.id}">${esc(ptext(p.id))}</option>`).join('')}</select></label>`:''}<label class="field">Issue title<input name="title" maxlength="100" required placeholder="Kitchen tap leaking"></label><div class="fieldgrid"><label class="field">Category<select name="category"><option>Plumbing</option><option>Electrical</option><option>General</option><option>Appliance</option></select></label><label class="field">Severity<select name="severity"><option>Routine</option><option>Urgent</option></select></label></div><label class="field">Tell us what’s happening<textarea name="description" required minlength="10" placeholder="Where is the issue, and when did it start?"></textarea></label><label class="field">Preferred contact window<input name="window" placeholder="Weekday mornings · demo preference"></label><label class="check"><input type="checkbox" name="photo" checked>Attach a synthetic maintenance image</label><div class="notice" style="margin-bottom:18px">Immediate danger? Call 000. Contact your agency directly for urgent repairs. This demo does not send real requests.</div><button class="primary">Submit request</button></form>`);
else if(a==='job-next'){await act('job',{id,next:b.dataset.next});toast('Work order updated.');render();}else if(a==='quote')openModal('Request owner approval',`<form id="quote-form" data-id="${id}"><label class="field">Proposed quote · AUD<input type="number" name="quote" min="1" max="10000" value="385" required></label><p class="note">Owner approval is recorded before quoted work is assigned. No money is collected.</p><button class="primary">Request approval</button></form>`);else if(a==='owner-decline')openModal('Return to the agency',`<form id="decline-form" data-id="${id}"><label class="field">Reason or request for details<textarea name="reason" required></textarea></label><button class="primary">Return for triage</button></form>`);else if(a==='schedule')openModal('Accept & propose an appointment',`<form id="schedule-form" data-id="${id}"><label class="field">Proposed date & time<input name="appointment" type="datetime-local" required></label><p class="note">Authorised demo access: arrange arrival with the agency. No keys or access codes are disclosed.</p><button class="primary">Accept work order</button></form>`);else if(a==='complete')openModal('Complete the work order',`<form id="complete-form" data-id="${id}"><label class="field">Completion notes<textarea name="completion" minlength="10" required placeholder="Replaced the tap cartridge and tested for leaks."></textarea></label><label class="check"><input type="checkbox" name="photo" required>Attach a synthetic completion image and demo invoice</label><button class="primary">Mark completed</button></form>`);else if(a==='variation')openModal('Request a variation',`<form id="variation-form" data-id="${id}"><label class="field">Additional cost · AUD<input type="number" min="1" max="10000" name="amount" required></label><label class="field">Why is it needed?<textarea name="reason" required></textarea></label><p class="note">Completion stays blocked until the agency approves the variation.</p><button class="primary">Request agency approval</button></form>`);else if(a==='variation-approve'){await act('job',{id,approveVariation:true});render();}
else if(a==='wizard-back'){await saveWizard(wizardStep-1);wizardStep--;render();}else if(a==='wizard-exit'){await saveWizard();go('/'+session.role);}else if(a==='wizard-edit'){await saveWizard(Number(b.dataset.step));wizardStep=Number(b.dataset.step);render();}else if(a==='demo-document'){$('#wizard-form [name=document]').value='synthetic-placeholder.pdf';$('#document-name').textContent='synthetic-placeholder.pdf';await saveWizard();toast('Synthetic placeholder added.');}else if(a==='preview-agreement')openModal('Demonstration agreement preview',`<span class="pill amber">Simulation · non-binding</span><h2 style="margin-top:20px">Proposed NSW-style tenancy agreement</h2><p class="note">Property: 12 Darling Street, Balmain NSW 2041 (fictional). Persona: Alex Morgan. Proposed term: 01 Nov 2026 – 31 Oct 2027. Proposed rent: $850/week.</p><p class="notice">DEMONSTRATION — FICTIONAL. This is an illustrative summary, not a standard agreement or legal template. No signature or bond is verified.</p><p class="note">Production onboarding requires the appropriate agreement, tenant information statement, condition report, applicable by-laws and Rental Bonds Online invitation, with legal review.</p>`);
else if(a==='document'){const r=await fetch('/api/document/'+id,{headers:{Authorization:'Bearer '+session.token}});if(!r.ok)throw Error('Document access denied.');const html=await r.text();openModal('Synthetic document',`<iframe title="Fictional document preview" style="width:100%;height:380px;border:1px solid #ddd" srcdoc="${esc(html)}"></iframe>${btn('Download demo preview','download-document',`data-id="${id}"`,'small')}`);}else if(a==='download-document'){const r=await fetch('/api/document/'+id,{headers:{Authorization:'Bearer '+session.token}});if(!r.ok)throw Error('Document unavailable');download(new Blob([await r.text()],{type:'text/html'}),'demonstration-fictional.html');}
else if(a==='notifications')go('/'+session.role+'/notifications');else if(a==='read-notifications'){await act('notify_read');render();}else if(a==='sync'){await act('sync',{id,failure:b.dataset.failure==='true'});render();}else if(a==='add-property')openModal('Add a fictional property',`<form id="property-form"><label class="field">Street address<input name="address" required placeholder="Demonstration address only"></label><label class="field">Suburb<input name="suburb" required></label><p class="note">Use a fictional example. No real client information.</p><button class="primary">Add property</button></form>`);else if(a==='activity')openModal('A connected activity trail',state?timeline(state.audit,50):'<p class="note">Launch the agency workspace to see its audit trail.</p>');else if(a==='integration')openModal('Works alongside the agency’s software',`<p class="note">PropertyTag is a proposed orchestration layer. The demo adapter shows contact, tenancy and maintenance sync requests with deterministic success, failure and retry.</p><p class="notice">No live PropertyMe, PropertyTree or other integration is connected. API access, data mapping and commercial permissions must be confirmed with the agency and vendor.</p>${btn('Open simulated sync ledger','scenario','data-role="agency" data-path="/agency/settings"','primary small')}`);else if(a==='tour')openModal('Your 8–10 minute walkthrough',`<div class="tourstep">1. Agency: invite Alex Morgan to 12 Darling Street and show the printable tag.</div><div class="tourstep">2. Tenant: claim the invitation, save and submit six onboarding steps.</div><div class="tourstep">3. Agency: review details, document and agreement; approve and activate.</div><div class="tourstep">4. Owner: approve the $385 plumbing quote.</div><div class="tourstep">5. Agency: assign Sam. Contractor: accept, schedule, start and complete.</div><div class="tourstep">6. Tenant: see the completed request. Agency: verify, close and inspect the audit trail.</div>${btn('Start at the agency','role','data-role="agency"','primary')}`);else if(a==='reset')openModal('Reset this shared demonstration?',`<p class="note">This restores the fictional opening portfolio and removes all changes, tags and requests created during this presentation. Other open tabs will show the reset on their next refresh.</p>${btn('Yes, restore opening state','confirm-reset','','danger')}${btn('Keep my changes','close','','small')}`);else if(a==='confirm-reset'){if(session?.role!=='agency'){await sign('agency');}await act('reset');closeModal();wizardStep=0;go('/agency');toast('Opening scenario restored.');}else if(a==='mobile'){if(!session){await sign('tenant');return;}openModal('Mobile portal preview',`<p class="note">This preview uses a separate tab-scoped demo persona. Pick a role inside it to follow the same shared data.</p><iframe title="Mobile property portal preview" src="/tenant" style="display:block;width:390px;max-width:100%;height:640px;margin:auto;border:1px solid #dce2d6;border-radius:18px"></iframe>`);}
}catch(e){if(!$('#toast').classList.contains('show'))toast(e.message);}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();const data=Object.fromEntries(new FormData(f));try{if(f.id==='search-form'){query=data.q;history.pushState({},'','/agency/properties');render();}else if(f.id==='invite-form'){const r=await act('invite',{...data,expired:!!data.expired});const p=property(data.property);const url=location.origin+(data.role==='hub'?'/tag/'+p.code:'/invite/'+r.token);showQR(url,p.address+' · '+(data.role==='hub'?'Public guide':roles[data.role]),data.role);}else if(f.id==='wizard-form'){if(wizardStep===2&&!data.document){toast('Add a synthetic document first.');return;}const d=saveDraftData();if(wizardStep===5){await act('submit_onboarding',{id:f.dataset.id,data:d,step:5});toast('Submitted. Your agency review task is ready.');}else{await act('save_onboarding',{id:f.dataset.id,data:d,step:wizardStep+1});wizardStep++;}render();window.scrollTo(0,0);}else if(f.id==='claim-form'){session=await api('invite',{token:f.dataset.token,confirm:!!data.confirm});sessionStorage.setItem('pt-session',JSON.stringify(session));state=await api('state');wizardStep=state.onboarding.find(o=>o.person===session.person)?.step||0;go('/'+session.role+'/onboarding');}else if(f.id==='correction-form'){await act('review_onboarding',{id:f.dataset.id,next:'changes_requested',reason:data.reason});closeModal();render();}else if(f.id==='job-form'){const r=await act('create_job',{...data,photo:!!data.photo});closeModal();go('/'+session.role+'/maintenance/'+r.id);toast('Request '+r.id+' created.');}else if(f.id==='comment-form'){await act('job',{id:f.dataset.id,comment:data.comment});render();toast('Reply added.');}else if(['quote-form','decline-form','schedule-form','complete-form','variation-form'].includes(f.id)){const next={'quote-form':'awaiting_owner_approval','decline-form':'triage','schedule-form':'scheduled','complete-form':'completed'}[f.id];await act('job',{id:f.dataset.id,...data,next,photo:!!data.photo,variation:f.id==='variation-form'});closeModal();render();toast('Work order updated.');}else if(f.id==='settings-form'){await act('settings',data);render();toast('Agency theme saved.');}else if(f.id==='property-form'){const r=await act('add_property',data);closeModal();go('/agency/properties/'+r.id);toast('Fictional property added.');}else if(f.id==='profile-form'){await act('profile',data);toast('Demo preferences recorded.');}}catch(e){toast(e.message);}});
let autosaveTimer;
document.addEventListener('input',e=>{if(e.target.closest('#report-form'))calcReport();if(e.target.id==='portfolio-search'){query=e.target.value;const start=e.target.selectionStart;render();$('#portfolio-search').focus();$('#portfolio-search').setSelectionRange(start,start);}if(e.target.closest('#wizard-form')&&e.target.type!=='file'){clearTimeout(autosaveTimer);$('#save-state').textContent='Saving…';autosaveTimer=setTimeout(async()=>{try{await saveWizard();if($('#save-state'))$('#save-state').textContent='Draft saved · resumes here';}catch{}},700);}});
document.addEventListener('change',async e=>{if(e.target.id==='synthetic-upload'){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024||!['application/pdf','image/png','image/jpeg'].includes(file.type)||!/\.(pdf|png|jpe?g)$/i.test(file.name)){toast('Choose PDF / JPG / PNG up to 5 MB.');e.target.value='';return;}$('#wizard-form [name=document]').value='demo-'+file.name.slice(0,80);$('#document-name').textContent='demo-'+file.name;await saveWizard();toast('Filename saved. File contents were not uploaded.');}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search-form input')?.focus();}});
document.addEventListener('click',e=>{if(e.target.closest('a[data-nav]'))closeModal();});
window.addEventListener('popstate',render);
async function init(){if(session){try{state=await api('state');wizardStep=state.onboarding.find(o=>o.person===session.person)?.step||0;}catch{session=null;sessionStorage.removeItem('pt-session');}}render();}
setInterval(async()=>{if(!session||!state||saving||polling||$('#modal').open||document.activeElement?.matches('input,textarea,select')||$('#wizard-form'))return;polling=true;try{const next=await api('state');if(JSON.stringify(next)!==JSON.stringify(state)){state=next;render();}}catch{}finally{polling=false;}},5000);
init();
